 "content": "def transform(grid):
    # Recolor the contiguous 9-shape lying under/adjacent to a long 3-color marker line
    # in the demo, but more generally marker line seems color 8/5 and nearest shape becomes that color.
    h=len(grid); w=len(grid[0]); g=[r[:] for r in grid]
    # Long straight marker of color C has an adjacent object in a different color; recolor
    # connected component of that adjacent color, excluding background.
    from collections import Counter, deque
    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    for color in range(10):
        # identify long contiguous horizontal/vertical color runs >=5
        runs=[]
        for r in range(h):
            c=0
            while c<w:
                k=c+1
                while k<w and g[r][k]==g[r][c]: k+=1
                if g[r][c]==color and k-c>=5: runs.append([(r,j) for j in range(c,k)])
                c=k
        for c in range(w):
            r=0
            while r<h:
                k=r+1
                while k<h and g[k][c]==g[r][c]: k+=1
                if g[r][c]==color and k-r>=5: runs.append([(j,c) for j in range(r,k)])
                r=k
        for run in runs:
            for r,c in run:
                for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    y,x=r+dr,c+dc
                    if not(0<=y<h and 0<=x<w) or g[y][x] in (bg,color): continue
                    src=g[y][x]
                    q=deque([(y,x)]); comp={(y,x)}
                    while q:
                        a,b=q.popleft()
                        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                            aa,bb=a+dy,b+dx
                            if 0<=aa<h and 0<=bb<w and (aa,bb) not in comp and g[aa][bb]==src:
